// The neural grapheme-to-phoneme (G2P) model's inference - letters to ARPAbet phones with stress, for every word PicoVox
// speaks (no pronouncing dictionary at runtime). The model (lib/models/g2pModel.js, generated by picovox_train.context export) is a
// manifest and its quantized weights as base64; loadG2p decodes it once (asynchronously - the weights may be deflated)
// and returns a fast synchronous pronounce function with a per-word cache.
//
// The design ("ar"): a bidirectional GRU encoder over the letters, a GRU decoder over the previous phones (started from
// the encoder's ends), dot-product attention, and greedy decoding until <eos>. For speed, the GRUs' input projections of
// letters and phones are lookup tables (computed at load), the attention's keys and the combine layer's context half are
// computed once per word, and the buffers are preallocated.
//
// Heteronyms (the model's "readings" and its "context" section - picovox_train/context.py): the decoder's initial state adds a
// learned vector per alternate reading (reading 0, the default, adds nothing), and an ambiguity head (a tanh layer and a
// logit) on the encoder's final states says whether a word has readings its neighbors decide. For such a word, the
// context network - a character GRU reading each of the window's items (the words and phrase-end marks around the word)
// to a vector, a bidirectional GRU over the window, its middle outputs' tanh layer gated by the word's own vector's, and
// the reading slots' logits - chooses the reading. No word list or rule.
//
// Words in capitals: a spelled head (a tanh layer and two logits on the encoder's final states, as the ambiguity head)
// says whether a word written in capitals is spelled - its letters' names ("AI", "TOC") - or read as a word ("NOT",
// "NASA"): one logit for a word alone among lowercase words ("the US government" - spelled), one for a word beside words
// in capitals ("LEAVE US ALONE" - read).

import {decodeBase64, inflateRaw} from './package.js';


// A model section's weight bytes - its base64, inflated if it's deflated
async function weightBytes(section) {
    const bytes = decodeBase64(section.weights);
    return section.deflate ? new Uint8Array(await inflateRaw(bytes)) : bytes;
}


// Unpack the model's tensors from its weight bytes - a Map of name to Float64Array (row-major). The bytes are every
// tensor's scales (bfloat16, one per row), then every tensor's values - signed integers of the
// tensor's bits, offset to unsigned, each tensor starting on a byte - packed little-endian bit by bit ("packed") or a
// byte each ("bytes"). A weight is its integer times its scale.
export function unpackTensors(model, bytes) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const scaleView = new DataView(new ArrayBuffer(4));
    const shapes = model.tensors.map(({shape}) => (shape.length === 1 ? [1, shape[0]] : shape));

    // The scales
    let offset = 0;
    const scales = shapes.map(([rows]) => {
        const values = new Float64Array(rows);
        for (let ix = 0; ix < values.length; ix++) {
            scaleView.setUint32(0, view.getUint16(offset, true) << 16);
            values[ix] = scaleView.getFloat32(0);
            offset += 2;
        }
        return values;
    });

    // The values
    const tensors = new Map();
    for (const [index, {name, bits}] of model.tensors.entries()) {
        const [rows, columns] = shapes[index];
        const values = new Float64Array(rows * columns);
        const zero = (1 << (bits - 1)) - 1;
        let bit = 0;
        for (let ix = 0; ix < values.length; ix++) {
            let unsigned;
            if (model.layout === 'bytes') {
                unsigned = bytes[offset + ix];
            } else {
                unsigned = 0;
                for (let bitIndex = 0; bitIndex < bits; bitIndex++, bit++) {
                    unsigned |= ((bytes[offset + (bit >> 3)] >> (bit & 7)) & 1) << bitIndex;
                }
            }
            values[ix] = (unsigned - zero) * scales[index][Math.floor(ix / columns)];
        }
        offset += model.layout === 'bytes' ? values.length : Math.ceil(bit / 8);
        tensors.set(name, values);
    }
    return tensors;
}


// result[0:rows] = matrix[rows, columns] @ vector (from vectorOffset) + bias (null for none), into a preallocated result
// (not the vector) - each row's sum in its columns' order, as a row at a time sums it. The columns are taken sixteen at
// a time down the rows, the vector's values in locals, and then the columns past a multiple of sixteen one at a time -
// for engines without a JIT, where an array read costs several times a product of locals (the paper's Section 12.4)
export function matrixVector(result, matrix, rows, columns, vector, vectorOffset, bias) {
    for (let row = 0; row < rows; row++) {
        result[row] = bias === null ? 0 : bias[row];
    }
    let column = 0;
    for (; column + 16 <= columns; column += 16) {
        const base = vectorOffset + column;
        const v00 = vector[base]; const v01 = vector[base + 1]; const v02 = vector[base + 2]; const v03 = vector[base + 3];
        const v04 = vector[base + 4]; const v05 = vector[base + 5]; const v06 = vector[base + 6]; const v07 = vector[base + 7];
        const v08 = vector[base + 8]; const v09 = vector[base + 9]; const v10 = vector[base + 10]; const v11 = vector[base + 11];
        const v12 = vector[base + 12]; const v13 = vector[base + 13]; const v14 = vector[base + 14]; const v15 = vector[base + 15];
        for (let row = 0, ix = column; row < rows; row++, ix += columns) {
            result[row] = result[row] + matrix[ix] * v00 + matrix[ix + 1] * v01 + matrix[ix + 2] * v02 + matrix[ix + 3] * v03 +
                matrix[ix + 4] * v04 + matrix[ix + 5] * v05 + matrix[ix + 6] * v06 + matrix[ix + 7] * v07 +
                matrix[ix + 8] * v08 + matrix[ix + 9] * v09 + matrix[ix + 10] * v10 + matrix[ix + 11] * v11 +
                matrix[ix + 12] * v12 + matrix[ix + 13] * v13 + matrix[ix + 14] * v14 + matrix[ix + 15] * v15;
        }
    }
    for (; column < columns; column++) {
        const value = vector[vectorOffset + column];
        for (let row = 0, ix = column; row < rows; row++, ix += columns) {
            result[row] += matrix[ix] * value;
        }
    }
}


// The input gate projections of every row of an embedding table - [rows, gates]
function inputTable(gru, embedding, rows, width) {
    const gates = 3 * gru.hidden;
    const table = new Float64Array(rows * gates);
    const row = new Float64Array(gates);
    for (let id = 0; id < rows; id++) {
        matrixVector(row, gru.inputWeights, gates, width, embedding, id * width, gru.inputBias);
        table.set(row, id * gates);
    }
    return table;
}


// A GRU step from its input gates (PyTorch's gate order and formula: r, z, n; h' = n + z * (h - n)) - updates the state
// in place
function gruStep(gru, gates, gatesOffset, state, scratch) {
    const {hidden} = gru;
    matrixVector(scratch, gru.stateWeights, 3 * hidden, hidden, state, 0, gru.stateBias);
    for (let ix = 0; ix < hidden; ix++) {
        const reset = 1 / (1 + Math.exp(-(gates[gatesOffset + ix] + scratch[ix])));
        const update = 1 / (1 + Math.exp(-(gates[gatesOffset + hidden + ix] + scratch[hidden + ix])));
        const candidate = Math.tanh(gates[gatesOffset + 2 * hidden + ix] + reset * scratch[2 * hidden + ix]);
        state[ix] = candidate + update * (state[ix] - candidate);
    }
}


// A GRU's weights from the tensors by PyTorch name prefix and suffix (for example, "encoder", "_reverse")
function gruWeights(tensors, prefix, suffix, hidden) {
    return {
        hidden,
        'inputWeights': tensors.get(`${prefix}.weight_ih_l0${suffix}`),
        'stateWeights': tensors.get(`${prefix}.weight_hh_l0${suffix}`),
        'inputBias': tensors.get(`${prefix}.bias_ih_l0${suffix}`),
        'stateBias': tensors.get(`${prefix}.bias_hh_l0${suffix}`)
    };
}


// Run the bidirectional encoder over letter ids (their input gates from the lookup tables) - each step's output into
// outputs ([steps, 2H], forward then backward), and the final states (forward then backward) into ends
function encode(encoder, ids, outputs, ends, scratch) {
    const {forward, backward, forwardTable, backwardTable} = encoder;
    const {hidden} = forward;
    const gates = 3 * hidden;
    const state = new Float64Array(hidden);
    for (let step = 0; step < ids.length; step++) {
        gruStep(forward, forwardTable, ids[step] * gates, state, scratch);
        outputs.set(state, step * 2 * hidden);
    }
    ends.set(state, 0);
    state.fill(0);
    for (let step = ids.length - 1; step >= 0; step--) {
        gruStep(backward, backwardTable, ids[step] * gates, state, scratch);
        outputs.set(state, step * 2 * hidden + hidden);
    }
    ends.set(state, hidden);
}


// tanh of the first count values, in place
function tanhInPlace(values, count) {
    for (let ix = 0; ix < count; ix++) {
        values[ix] = Math.tanh(values[ix]);
    }
}


// The index of the largest of the first count values (the first, on ties)
function argmax(values, count) {
    let best = 0;
    for (let ix = 1; ix < count; ix++) {
        if (values[ix] > values[best]) {
            best = ix;
        }
    }
    return best;
}


// Load the context network (a G2P model's "context" section) - returns chooseReading(items, index), the reading slot of
// the word at index in a text's items (its words, and its phrase ends as ',', '.', '?', '!'), cached per window
async function loadContext(context) {
    const tensors = unpackTensors(context, await weightBytes(context));
    const {embed, hidden, layer, slots, window, maxChars} = context;
    const charGru = gruWeights(tensors, 'char_gru', '', hidden);
    const charTable = inputTable(charGru, tensors.get('char_embed.weight'), context.chars.length + 1, embed);
    const forward = gruWeights(tensors, 'window_gru', '', hidden);
    const backward = gruWeights(tensors, 'window_gru', '_reverse', hidden);
    const layerWeights = tensors.get('layer.weight');
    const layerBias = tensors.get('layer.bias');
    const wordWeights = tensors.get('word_layer.weight');
    const wordBias = tensors.get('word_layer.bias');
    const output = tensors.get('output.weight');
    const outputBias = tensors.get('output.bias');
    const charIds = new Map([...context.chars].map((char, ix) => [char, ix + 1]));
    const gates = new Float64Array(3 * hidden);
    const scratch = new Float64Array(3 * hidden);
    const joined = new Float64Array(2 * hidden);
    const hiddenLayer = new Float64Array(layer);
    const wordLayer = new Float64Array(layer);
    const logits = new Float64Array(slots);
    const zero = new Float64Array(hidden);

    // An item's vector - the character GRU's final state over its last maxChars characters (zero for no characters),
    // cached per item
    const vectors = new Map();
    const itemVector = (item) => {
        let vector = vectors.get(item);
        if (vector === undefined) {
            vector = new Float64Array(hidden);
            const ids = [...item].filter((char) => charIds.has(char)).slice(-maxChars);
            for (const char of ids) {
                gruStep(charGru, charTable, charIds.get(char) * 3 * hidden, vector, scratch);
            }
            vectors.set(item, vector);
        }
        return vector;
    };

    // Run a direction of the window GRU over the window's vectors (in order) - its final state into joined at offset
    const runWindow = (gru, windowVectors, offset) => {
        const state = new Float64Array(hidden);
        for (const vector of windowVectors) {
            matrixVector(gates, gru.inputWeights, 3 * hidden, hidden, vector, 0, gru.inputBias);
            gruStep(gru, gates, 0, state, scratch);
        }
        joined.set(state, offset);
    };

    const choices = new Map();
    return (items, index) => {
        const windowItems = [];
        for (let position = index - window; position <= index + window; position++) {
            windowItems.push(position >= 0 && position < items.length ? items[position] : '');
        }
        const key = windowItems.join(' ');
        let choice = choices.get(key);
        if (choice === undefined) {
            const windowVectors = windowItems.map((item) => (item === '' ? zero : itemVector(item)));
            runWindow(forward, windowVectors.slice(0, window + 1), 0);
            runWindow(backward, windowVectors.slice(window).reverse(), hidden);
            matrixVector(hiddenLayer, layerWeights, layer, 2 * hidden, joined, 0, layerBias);
            matrixVector(wordLayer, wordWeights, layer, hidden, windowVectors[window], 0, wordBias);
            for (let ix = 0; ix < layer; ix++) {
                hiddenLayer[ix] = Math.tanh(hiddenLayer[ix]) * Math.tanh(wordLayer[ix]);
            }
            matrixVector(logits, output, slots, layer, hiddenLayer, 0, outputBias);
            choice = argmax(logits, slots);
            choices.set(key, choice);
        }
        return choice;
    };
}


// Load a G2P model (lib/models/g2pModel.js's g2pModel) - returns pronounce(word, reading = 0), the word's ARPAbet phones
// with stress (for example, ['K', 'W', 'IY1', 'K', 'W', 'EH2', 'G']) in a reading, cached per word and reading.
// pronounce also has ambiguous(word) (the ambiguity head - whether the word's reading depends on its neighbors),
// chooseReading(items, index) (the context network's reading for the word at index in a text's items), and
// spelled(word, beside = false) (the spelled head - whether the word, written in capitals, is spelled: its letters'
// names - alone among lowercase words, or beside a word in capitals).
export async function loadG2p(model) {
    const tensors = unpackTensors(model, await weightBytes(model));
    const {embed, hidden, decoder, maxLetters} = model;
    const phoneCount = model.phones.length;
    const letterEmbed = tensors.get('letter_embed.weight');
    const forward = gruWeights(tensors, 'encoder', '', hidden);
    const backward = gruWeights(tensors, 'encoder', '_reverse', hidden);
    const encoder = {
        forward, backward,
        'forwardTable': inputTable(forward, letterEmbed, model.letters.length + 1, embed),
        'backwardTable': inputTable(backward, letterEmbed, model.letters.length + 1, embed)
    };
    const decoderGru = gruWeights(tensors, 'decoder', '', decoder);
    const phoneTable = inputTable(decoderGru, tensors.get('phone_embed.weight'), phoneCount, embed);
    const combineBias = tensors.get('combine.bias');
    const output = tensors.get('output.weight');
    const outputBias = tensors.get('output.bias');
    const bridge = tensors.get('bridge.weight');
    const bridgeBias = tensors.get('bridge.bias');
    const readingWeights = tensors.get('reading.weight');
    const ambiguityLayer = tensors.get('ambiguity_layer.weight');
    const ambiguityLayerBias = tensors.get('ambiguity_layer.bias');
    const ambiguityWeights = tensors.get('ambiguity.weight');
    const ambiguityBias = tensors.get('ambiguity.bias');
    const spelledLayer = tensors.get('spelled_layer.weight');
    const spelledLayerBias = tensors.get('spelled_layer.bias');
    const spelledWeights = tensors.get('spelled.weight');
    const spelledBias = tensors.get('spelled.bias');
    const width = 2 * hidden;

    // The attention's weights transposed ([decoder, width] - a letter's key is attention^T @ its encoder output), and the
    // combine layer's weights' two halves ([decoder, decoder] of the decoder's state, [decoder, width] of the context)
    const attention = tensors.get('attention.weight');
    const combine = tensors.get('combine.weight');
    const attentionTransposed = new Float64Array(decoder * width);
    const combineState = new Float64Array(decoder * decoder);
    const combineContext = new Float64Array(decoder * width);
    for (let row = 0; row < decoder; row++) {
        for (let column = 0; column < width; column++) {
            attentionTransposed[row * width + column] = attention[column * decoder + row];
        }
        const combineRow = row * (decoder + width);
        combineState.set(combine.subarray(combineRow, combineRow + decoder), row * decoder);
        combineContext.set(combine.subarray(combineRow + decoder, combineRow + decoder + width), row * width);
    }

    // Preallocated buffers - the encoder's outputs, the letters' attention keys ([letters, decoder] - and each letter's
    // row of them), and each letter's context value (the combine layer's context half of its encoder output)
    const encoded = new Float64Array(maxLetters * width);
    const keys = new Float64Array(maxLetters * decoder);
    const letterKeys = Array.from({'length': maxLetters}, (_unused, step) => keys.subarray(step * decoder, (step + 1) * decoder));
    const letterValues = Array.from({'length': maxLetters}, () => new Float64Array(decoder));
    const scratch = new Float64Array(3 * Math.max(hidden, decoder));
    const ends = new Float64Array(width);
    const state = new Float64Array(decoder);
    const combined = new Float64Array(decoder);
    const logits = new Float64Array(phoneCount);
    const weights = new Float64Array(maxLetters);
    const ambiguity = new Float64Array(1);
    const ambiguityHidden = new Float64Array(ambiguityLayerBias.length);
    const spelled = new Float64Array(2);
    const spelledHidden = new Float64Array(spelledLayerBias.length);

    // Pronounce letter ids in a reading - phone ids (and the ambiguity and spelled heads' logits into ambiguity and
    // spelled)
    const pronounceIds = (ids, reading) => {
        const steps = ids.length;
        encode(encoder, ids, encoded, ends, scratch);
        matrixVector(state, bridge, decoder, width, ends, 0, bridgeBias);
        tanhInPlace(state, decoder);
        matrixVector(ambiguityHidden, ambiguityLayer, ambiguityHidden.length, width, ends, 0, ambiguityLayerBias);
        tanhInPlace(ambiguityHidden, ambiguityHidden.length);
        matrixVector(ambiguity, ambiguityWeights, 1, ambiguityHidden.length, ambiguityHidden, 0, ambiguityBias);
        matrixVector(spelledHidden, spelledLayer, spelledHidden.length, width, ends, 0, spelledLayerBias);
        tanhInPlace(spelledHidden, spelledHidden.length);
        matrixVector(spelled, spelledWeights, 2, spelledHidden.length, spelledHidden, 0, spelledBias);
        if (reading > 0) {
            for (let ix = 0; ix < decoder; ix++) {
                state[ix] += readingWeights[(reading - 1) * decoder + ix];
            }
        }

        // Each letter's attention key (attention^T @ encoded) and context value (combine's context half @ encoded)
        for (let step = 0; step < steps; step++) {
            matrixVector(letterKeys[step], attentionTransposed, decoder, width, encoded, step * width, null);
            matrixVector(letterValues[step], combineContext, decoder, width, encoded, step * width, null);
        }

        // Decode greedily until <eos> - at most 3 phones a letter, plus 6 (the letter "w" is 7 phones)
        const phones = [];
        let previous = 1;
        for (let phoneStep = 0; phoneStep < 3 * steps + 6; phoneStep++) {
            gruStep(decoderGru, phoneTable, previous * 3 * decoder, state, scratch);
            matrixVector(weights, keys, steps, decoder, state, 0, null);
            let maxScore = -Infinity;
            for (let letter = 0; letter < steps; letter++) {
                maxScore = Math.max(maxScore, weights[letter]);
            }
            let total = 0;
            for (let letter = 0; letter < steps; letter++) {
                weights[letter] = Math.exp(weights[letter] - maxScore);
                total += weights[letter];
            }
            matrixVector(combined, combineState, decoder, decoder, state, 0, combineBias);
            for (let letter = 0; letter < steps; letter++) {
                const weight = weights[letter] / total;
                const letterValue = letterValues[letter];
                for (let row = 0; row < decoder; row++) {
                    combined[row] += weight * letterValue[row];
                }
            }
            tanhInPlace(combined, decoder);
            matrixVector(logits, output, phoneCount, decoder, combined, 0, outputBias);
            const best = argmax(logits, phoneCount);
            if (best <= 1) {
                break;
            }
            phones.push(best);
            previous = best;
        }
        return phones;
    };

    // The pronouncer - phones cached per reading and word, the ambiguity and spelled heads' decisions per word (made when
    // the word is first pronounced)
    const letterIds = new Map([...model.letters].map((letter, ix) => [letter, ix + 1]));
    const caches = Array.from({'length': model.readings}, () => new Map());
    const ambiguousWords = new Map();
    const spelledWords = new Map();
    const pronounce = (word, reading = 0) => {
        const cache = caches[reading];
        let phones = cache.get(word);
        if (phones === undefined) {
            const ids = [...word].filter((letter) => letterIds.has(letter)).slice(0, maxLetters).map((letter) => letterIds.get(letter));
            phones = ids.length === 0 ? [] : pronounceIds(ids, reading).map((id) => model.phones[id]);
            cache.set(word, phones);
            if (reading === 0) {
                ambiguousWords.set(word, ids.length !== 0 && ambiguity[0] > 0);
                spelledWords.set(word, [ids.length !== 0 && spelled[0] > 0, ids.length !== 0 && spelled[1] > 0]);
            }
        }
        return phones;
    };
    pronounce.ambiguous = (word) => {
        if (!ambiguousWords.has(word)) {
            pronounce(word);
        }
        return ambiguousWords.get(word);
    };
    pronounce.spelled = (word, beside = false) => {
        if (!spelledWords.has(word)) {
            pronounce(word);
        }
        return spelledWords.get(word)[beside ? 1 : 0];
    };
    pronounce.chooseReading = await loadContext(model.context);
    return pronounce;
}
